function outputUnit(j,route,p){const r=j.results.find(r=>r.route===route&&r.placementId===p.id),busy=['queued','running'].includes(j.status),key=esc(route+'|'+p.id);return `<div class="unit"><div class="image-wrap">${r?.imageUrl?`<img src="${esc(r.imageUrl)}" alt="${esc(p.name+' · '+route)}" loading="lazy">`:`<div class="placeholder">${busy?'<i></i>':''}${busy?'Your image will appear here.':'No image available. Open details for more information.'}</div>`}</div><div class="unit-top"><strong>${esc(p.name)}</strong><span class="badge ${r?(r.ready?'':'flagged'):'pending'}">${r?(r.ready?'Ready':r.status==='no-output'?'No image':'Review before sharing'):busy?'In progress':'Unavailable'}</span></div>${r?`<div class="unit-actions">${r.imageUrl?`<button type="button" class="primary" data-canvas-open="${key}" aria-label="Edit design: ${esc(p.name+' · '+route)}">Edit design</button><a class="secondary" href="${esc(r.imageUrl)}" download>Download ↓</a>`:''}<button type="button" class="secondary" data-detail="${key}">View details</button></div>`:''}${r?.imageUrl?imageReactionHtml(j,r):''}</div>`;}

function renderOutputs(j,route){const seen=new Set();return j.placements.map(p=>{if(p.printSet){const c=p.printSet,key='print|'+c.id;if(seen.has(key))return '';seen.add(key);const pages=j.placements.filter(x=>x.printSet?.id===c.id).sort((a,b)=>a.printSet.index-b.printSet.index),proof=j.printProofs?.find(x=>x.route===route&&x.formatId===c.id),evidence=j.productionChecks?.filter(x=>x.route===route&&x.formatId===c.id&&x.masterPdfHash===proof?.pdfHash&&x.proofHash===proof?.physicalProof?.proofHash).at(-1);return `<section class="print-set"><div class="carousel-heading"><h3>${esc(c.name)}</h3><span class="badge pending">${pages.length} ${pages.length===1?'face':'pages / faces'} · PDF proof</span></div><p class="help">${proof?esc(proof.note):'PDF proof appears after all pages finish.'} Printer preflight is separate from image review.</p>${proof?.downloadUrl?`<a class="secondary" href="${esc(proof.downloadUrl)}" download>Download ordered PDF proof ↓</a> <a href="${esc(proof.reportUrl)}" download>Geometry & resolution report ↓</a>`:''}${proof?.actualSizeProofUrl?`<p><a class="secondary" href="${esc(proof.actualSizeProofUrl)}" download>Download calibrated A4 proof ↓</a> <a href="${esc(proof.preflightUrl)}" download>Production preflight report ↓</a></p><p class="help">${esc(proof.physicalProof.fullCoverage?'Full artwork tile coverage. Print at 100% and measure the 50 mm line.':'Partial actual-size samples only. Complete installed-size proof still required.')} Production: ${esc(proof.preflight.status.replaceAll('-',' '))}.</p>${evidence?`<p class="help">Recorded checks: ${esc(evidence.status.replaceAll('-',' '))}. <a href="${esc(evidence.reportUrl)}" download>Recorded evidence report ↓</a></p>`:''}<button type="button" class="secondary" data-production="${esc(route+'|'+c.id)}">Record physical / operator evidence →</button>`:''}<div class="print-pages">${pages.map(x=>outputUnit(j,route,x)).join('')}</div></section>`;}if(!p.carousel)return outputUnit(j,route,p);const c=p.carousel;if(seen.has(c.id))return '';seen.add(c.id);const slides=j.placements.filter(x=>x.carousel?.id===c.id).sort((a,b)=>a.carousel.index-b.carousel.index),key=route+'|'+c.id,active=Math.min(carouselPages[key]||0,slides.length-1),set=j.carousels?.find(s=>s.route===route&&s.carouselId===c.id),plan=j.carouselPlan?.sets.find(s=>s.carouselId===c.id&&s.conceptId===j.concepts?.find(x=>x.route===route)?.conceptId),ready=slides.filter(x=>j.results.find(r=>r.route===route&&r.placementId===x.id)?.ready).length;return `<section class="carousel-set"><div class="carousel-heading"><div><span class="eyebrow">CAROUSEL · ${slides.length} SLIDES</span><h3>${esc(plan?.title||c.name)}</h3></div><span class="badge ${set?(set.ready?'':'flagged'):'pending'}">${set?(set.ready?'Set ready':'Set needs review'):ready+' / '+slides.length+' slides ready'}</span></div><p class="carousel-rationale">${esc(plan?.rationale||'The sequence plan will appear after the concepts are saved.')}</p>${outputUnit(j,route,slides[active])}<nav class="carousel-nav" aria-label="Carousel slide navigation"><button type="button" class="secondary" data-carousel="${esc(key)}" data-slide="${active-1}" ${active===0?'disabled':''} aria-label="Previous slide">←</button>${slides.map((s,i)=>{const result=j.results.find(r=>r.route===route&&r.placementId===s.id);return `<button type="button" class="slide-dot ${i===active?'active':''}" data-carousel="${esc(key)}" data-slide="${i}" aria-label="Slide ${i+1}${result?.ready?', ready':''}" aria-current="${i===active?'true':'false'}">${i+1}${result?.ready?' ✓':''}</button>`;}).join('')}<button type="button" class="secondary" data-carousel="${esc(key)}" data-slide="${active+1}" ${active===slides.length-1?'disabled':''} aria-label="Next slide">→</button></nav>${plan?`<details class="carousel-story"><summary>Story & slide order</summary><p>${esc(plan.visualSystem)}</p>${plan.slides.map((s,i)=>`<div><b>${i+1} · ${esc(s.role)}</b><p>${esc(s.message)}</p><small>${esc(s.transition)}</small></div>`).join('')}</details>`:''}${set?`<div class="carousel-checks">${set.checks.map(x=>`<p><span class="badge ${x.status==='pass'?'':x.status==='fail'?'flagged':'pending'}">${esc(x.status)}</span> ${esc(x.criterion.replaceAll('-',' '))}</p>`).join('')}<p class="help">${esc(set.note)}</p>${set.downloadUrl?`<a class="primary" href="${esc(set.downloadUrl)}" download>Download ${set.ready?'carousel':'set for review'} ↓</a>`:'<p class="help">Changed sequence: export selected artwork separately; a new full-set review is required.</p>'}<a class="back-link" href="${esc(set.reviewUrl)}" target="_blank">Set review ↗</a></div>`:''}</section>`;}).join('');}
function render(j){activeBrand=brandList.find(b=>belongs(j,b))||null;renderBrandNav();currentJob=j;if(detailKey)return;$('#progressPanel').hidden=!['queued','running'].includes(j.status);$('#generateRecovered').hidden=!(j.status==='partial'&&j.artifacts.artReconciliationRecovery?.status==='art-stage-recovered'&&!j.generationRecovery&&!j.results.length);const recovered=j.status==='partial'&&j.artifacts.artReconciliationRecovery?.status==='art-stage-recovered'&&!j.generationRecovery&&!j.results.length;screen('project',recovered?2:['queued','running'].includes(j.status)?2:3);$('#projectTitle').textContent=recovered?'Art planning recovered':['queued','running'].includes(j.status)?'Your ideas are taking shape':j.status==='finished'?'Your images, two directions':j.status==='needs-input'?'Add the product page':'Your project needs attention';$('#projectMeta').textContent=new URL(j.brandUrl).hostname+' · '+new Set(j.placements.map(p=>p.formatId||p.id)).size+' format'+(new Set(j.placements.map(p=>p.formatId||p.id)).size===1?'':'s')+' · '+new Date(j.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'});$('#progressLabel').textContent=recovered?'Layouts validated · awaiting images':j.status==='finished'?(j.results.every(r=>r.ready)&&!j.carousels?.some(c=>!c.ready)?'Ready':'Review complete'):j.status==='needs-input'?'Product page needed':j.progress.label.replace('Creating statics','Creating images');$('#outputCount').textContent=j.results.filter(r=>r.imageUrl).length+' / '+j.progress.totalOutputs+' images';$('#stages').innerHTML=j.stages.map(s=>`<li class="${esc(s.status)} ${s.id===j.progress.stage?'current':''}">${esc(s.id==='ready'&&j.status==='finished'&&(!j.results.every(r=>r.ready)||j.carousels?.some(c=>!c.ready))?'Review complete · issues':s.label.replace('Creating statics','Creating images'))}</li>`).join('');$('#activeAgents').textContent=recovered?'The saved layouts now pass validation. Image generation has not been resumed.':['queued','running'].includes(j.status)?(j.generationRecovery?'Creating images from your saved layouts in a separate bounded attempt. Each image appears as its checks finish.':'The tracker updates as each saved step completes. Images appear here when available.'):j.status==='finished'?'Generation and the bounded review cycle have finished. Open each image to see its reasoning and checks.':'Saved work is retained. Review the issue below.';$('#projectError').hidden=!j.error;$('#projectError').textContent=j.error||'';$('#productReferenceForm').hidden=j.status!=='needs-input';if(j.status==='needs-input')loadRequestedIdentities(j).catch(e=>{if(currentJob?.id===j.id)showError($('#productReferenceForm .form-error'),e);});$('#productReferencePrompt').textContent=j.productRequest?.message||'We need the product page before continuing.';$('#selectedProductPanel').hidden=!j.productSummary;if(j.productSummary)$('#selectedProductPanel').innerHTML='<span class="eyebrow">PRODUCT FOR THIS BRIEF</span><h3>'+esc(j.productSummary.name)+'</h3><p>'+esc(j.productSummary.assetCount)+' archived product image'+(j.productSummary.assetCount===1?'':'s')+' · Features sourced from the selected page</p><a target="_blank" rel="noopener" href="'+esc(j.productSummary.pageUrl)+'">View selected product page ↗</a>'+(j.productProtection?'<p><b>Selected SKU:</b> '+esc(j.productProtection.variant.sku)+' · '+esc(j.productProtection.variant.name)+' · '+esc(j.productProtection.angle)+'</p><p><b>Dimensions:</b> '+esc(skuDimensions(j.productProtection.variant))+'</p><p class="help">'+(j.productReferencePolicy?'Reference-led generation allows new angles, lighting and framing. Product branding and documented technology are preserved and reviewed across the complete creative.':'Historical full-photo lock: product pixels were placed after scene generation with uniform reduction and translation.')+'</p>':'');$('#dossierLink').hidden=!j.artifacts.dossier;if(j.artifacts.dossier)$('#dossierLink').href=j.artifacts.dossier.viewUrl;
 $('#strategyPanel').hidden=!j.strategy;if(j.strategy){$('#strategyContent').innerHTML=['get','who','to','by'].map(k=>`<div class="strategy-item"><b>${({get:'AUDIENCE',who:'CONTEXT & BARRIER',to:'DESIRED RESPONSE',by:'MESSAGE & PROOF'})[k]}</b><p>${esc(text(j.strategy[k]))}</p></div>`).join('');$('#strategyDownload').href='/creative-ai/api/jobs/'+j.id+'/files/'+(j.strategyFile||'strategy.json');}
 $('#resultsTitle').textContent=recovered?'Validated concepts & layouts':['queued','running'].includes(j.status)?'Concepts & images':'Your generated images';$('#resultStatus').textContent=recovered?j.artifacts.artReconciliationRecovery.specificationCount+' layouts validated · images not generated':j.results.length?j.results.filter(r=>r.ready).length+' ready · '+j.results.filter(r=>!r.ready).length+' need attention':j.concepts?.length?'Generating your images':'Concepts appear after strategy is saved';$('#results').innerHTML=['continuity','exploration'].map((route,i)=>{const c=j.concepts?.find(c=>c.route===route);return `<article class="concept"><div class="concept-head"><span class="eyebrow">0${i+1} · ${route==='continuity'?'BRAND CONTINUITY':'FRESH EXPLORATION'}</span><h3>${esc(c?.name||(route==='continuity'?'Build on your brand':'Explore a fresh expression'))}</h3><p>${esc(c?.publicExplanation?.idea||'The concept will appear once the working strategy is ready.')}</p></div>${renderOutputs(j,route)}</article>`;}).join('');loadImageReactions(j);}
$('#productReferenceForm').onsubmit=async e=>{e.preventDefault();const error=$('#productReferenceForm .form-error'),button=$('#resumeWithProduct');error.hidden=true;button.disabled=true;try{await post('/creative-ai/api/jobs/'+currentJob.id+'/product-page',{productPageUrl:$('#requestedProductPage').value.trim(),productIdentityId:$('#requestedProductIdentity').value});openJob(currentJob.id);}catch(e){showError(error,e);}finally{button.disabled=false;}};
async function poll(id){const epoch=navigationEpoch;try{const j=await api('/creative-ai/api/jobs/'+encodeURIComponent(id));if(epoch!==navigationEpoch)return;render(j);if(['queued','running'].includes(j.status))timer=setTimeout(()=>poll(id),2000);}catch(e){showError($('#projectError'),e);}}
