$('#results').onclick=e=>{const production=e.target.closest('[data-production]');if(production){openProductionEvidence(production.dataset.production);return;}const reaction=e.target.closest('[data-image-rating]');if(reaction){saveImageReaction(reaction);return;}const slide=e.target.closest('[data-carousel]');if(slide){carouselPages[slide.dataset.carousel]=Number(slide.dataset.slide);render(currentJob);return;}const button=e.target.closest('[data-detail]');if(button)openDetail(button.dataset.detail);};
const reasonCard=(title,content)=>`<section class="card"><h2>${esc(title)}</h2>${content}</section>`;
function detailNavigation(j,route,p){if(!p.carousel)return '';const rows=j.placements.filter(x=>x.carousel?.id===p.carousel.id).sort((a,b)=>a.carousel.index-b.carousel.index);return '<div class="detail-slide-nav">'+rows.map((x,i)=>`<button class="slide-dot ${x.id===p.id?'active':''}" data-detail="${esc(route+'|'+x.id)}" ${j.results.some(r=>r.route===route&&r.placementId===x.id)?'':'disabled'} aria-label="Review slide ${i+1}">${i+1}</button>`).join('')+'</div>';}
