// Condense saved intent only; do not infer observed placement or upgrade review status.
function designExcerpt(value,limit=115){const raw=typeof value==='string'?value:typeof value?.direction==='string'?value.direction:'';const clean=raw.split('Locked rules:')[0].replace(/\s+/g,' ').replace(/^(?:Place|Position) (?:the )?(?:supplied )?(?:horizontal )?logo (?:in|at) (?:the )?/i,'').replace(/where it remains /i,'→ ').replace(/Copywriter-supplied /g,'').replace(/genuine, uncluttered architectural wall space/i,'quiet wall space').replace(/^(?:Credible|Use|Reserve) /i,'').trim();if(clean.length<=limit)return clean;const end=clean.lastIndexOf(' ',limit-1);return clean.slice(0,end>limit/2?end:limit-1).replace(/[,;:]$/,'')+'…';}
function designSentence(value,pattern){return (typeof value==='string'?value:'').split(/(?<=[.!?])\s+/).find(x=>pattern.test(x))||'';}
function designPurpose(value){if(typeof value!=='string')return value;const clean=value.split('Locked rules:')[0].trim();const first=clean.split(/(?<=[.!?])\s+/)[0];const causal=first.match(/\b(?:while keeping|where it remains|to keep|to show|to reveal|to preserve|so that|because)\s+(.+)/i);if(causal){const choice=first.slice(0,causal.index).split(/\bwith enough\b/i)[0].trim();const verb=/^(?:while keeping|to keep)/i.test(causal[0])?'keep ':/^to preserve/i.test(causal[0])?'preserve ':'';return designExcerpt(choice,55)+' → '+designExcerpt(verb+causal[1],70);}const preserve=designSentence(clean,/^Preserve\b/i);if(preserve&&/daylight/i.test(first))return designExcerpt(first.split(',')[0],55)+' → '+designExcerpt(preserve.split(';')[0],70);return first||clean;}
function designIssueLabel(id){return ({'required-text-legibility':'Required text is hard to read','logo-identity':'Logo needs checking','product-identity':'Product identity needs checking','exact-required-copy':'Required wording needs checking','supported-claims':'Product claims need checking','verified-upload-constraints':'Export format needs checking'})[id]||String(id||'Artwork check').replace(/[-_]/g,' ');}
function designAtGlance(unit,result,placement){const a=unit?.plannedArt||{},composition=a.composition||'',logo=designSentence(composition,/\b(place|position|locate)\b.*\blogo\b/i)||a.logo?.treatment;const layout=designSentence(composition,/reserve|negative space|copy space|uncluttered|quiet.*(wall|zone)/i)||a.knowledgeApplications?.find(x=>x.principleId==='hierarchy')?.decision;const palette=(a.palette||[]).filter(x=>/wall|room|timber|accent|neutral/i.test(x)).slice(0,1).join(' ');const cards=[['◈','Logo',logo],['▤','Layout',layout?.split(', and a separate')[0]],['◎','Product & camera',designPurpose(a.camera||a.product?.treatment)],['◐','Colour',palette||a.palette?.join(' ')],['☀','Lighting',designPurpose(a.lighting)]];const pending=!result.qualityVerified;const issues=(unit?.review?.criticalChecks||[]).filter(x=>!['pass','not-applicable'].includes(x.status));return reasonCard('Design at a glance',
 '<p class="help glance-intent">Saved design intent · full reasons & sources below</p><div class="design-glance">'+cards.map(([icon,label,value])=>'<article class="design-choice"><span class="design-icon" aria-hidden="true">'+icon+'</span><div><h3>'+esc(label)+'</h3><p>'+esc(designExcerpt(value)||'Reason not recorded for this saved image.')+'</p></div></article>').join('')+'</div><div class="glance-check '+(pending||issues.length?'attention':'')+'"><b>'+ (pending?'○ Review pending':result.ready?'✓ Saved review passed':'⚠ Needs attention')+'</b><span>'+esc(pending?'These notes explain the plan; the rendered image is still unverified.':issues.length?issues.map(x=>designIssueLabel(x.criterion||x.id)).slice(0,3).join(' · '):'See the saved checks for execution details.')+'</span></div>');}
function brandGuidelineReasoning(unit){const reasoning=unit?.brandGuidelineReasoning;return reasonCard('Brand guidelines behind these choices',`<span class="pill">Intended guideline application</span>${reasoning?.applications?.length?reasoning.applications.map(a=>`<div class="review-check"><b>${esc(a.decision)}</b><p><strong>Guideline:</strong> ${esc(a.rule)}</p><p><strong>Why this was chosen:</strong> ${esc(a.why)}</p>${a.sources.map(s=>`<p class="help"><strong>${s.kind==='guidelines'?'Guideline source':'Supporting source'}:</strong> ${esc(s.reference?.startsWith('user-upload:')?s.reference.slice(12):s.label)} · ${esc(s.status)}${s.reference?.startsWith('https://')?` · <a href="${esc(s.reference)}" target="_blank" rel="noopener">View source ↗</a>`:''}</p>${s.note?`<details><summary>Source coverage & limits</summary><p class="help">${esc(s.note)}</p></details>`:''}`).join('')}</div>`).join(''):`<p>${reasoning?.recorded?'No specific brand-guideline application was recorded for this design.':'Specific guideline-to-choice explanations were not recorded for this saved image. New generations will save them here.'}</p>`}<p class="help">These explanations use the guidance saved with this image. They describe design intent; actual compliance is assessed in the artwork checks.</p>`);}
async function openDetail(key){const [route,placementId]=key.split('|'),job=currentJob,r=job?.results.find(r=>r.route===route&&r.placementId===placementId),p=job?.placements.find(p=>p.id===placementId);if(!r||!p){showError($('#projectError'),Error('This saved image is not available in this project.'));return;}const epoch=++navigationEpoch;detailKey=key;clearTimeout(timer);screen('detail',3);$('#imageFeedback').innerHTML='';loadImageFeedback(key,r).catch(e=>{if(epoch===navigationEpoch&&currentJob?.id===job.id&&detailKey===key)showError($('#detailError'),e);});history.replaceState(null,'','/creative-ai?job='+encodeURIComponent(currentJob.id)+'&image='+encodeURIComponent(key));$('#detailTitle').textContent=currentJob.concepts?.find(c=>c.route===route)?.name||'The idea behind the image';$('#detailSubtitle').textContent=(route==='continuity'?'Brand continuity':'Fresh exploration')+' · '+p.name;$('#detailStatus').className='badge '+(r.ready?'':'flagged');$('#detailStatus').textContent=r.ready?'Ready':r.qualityVerified?'Review before sharing':'Review pending';$('#detailPreview').innerHTML=r.imageUrl?`<img src="${esc(r.imageUrl)}" alt="${esc(p.name+' generated '+route+' image')}">`:'<p>No delivered image is available.</p>';$('#detailDownloads').innerHTML=detailNavigation(currentJob,route,p)+`${r.imageUrl?`<a class="primary" href="${esc(r.imageUrl)}" download>Download image ↓</a>`:''}${r.reviewUrl?`<a class="secondary" href="${esc(r.reviewUrl)}" target="_blank">Full review ↗</a>`:'<span class="help">No saved review is available.</span>'}`;$('#detailDownloads').insertAdjacentHTML('beforeend',window.EditableCanvas?.toolbar(key)||'');$('#detailError').hidden=true;$('#detailReasoning').innerHTML=reasonCard('Loading the saved reasoning','<p>Reading concept, design choices and artwork checks.</p>');window.scrollTo(0,0);try{const details=projectDetails||await api('/creative-ai/api/jobs/'+encodeURIComponent(job.id)+'/details');if(epoch!==navigationEpoch||currentJob?.id!==job.id||detailKey!==key)return;projectDetails=details;const u=projectDetails.units.find(u=>u.route===route&&u.placementId===placementId),a=u?.plannedArt,review=u?.review,guardian=projectDetails.guardian;const relevant=(guardian?.requirements||[]).concat((guardian?.visualRules||[]).map(v=>({...v,text:v.value}))); const visual=(review?.qualityScores||[]).filter(q=>['placementFit','visualCraft','communication','brandRecognition'].includes(q.criterion));$('#detailReasoning').innerHTML=designAtGlance(u,r,p)+'<details class="reasoning-details"><summary>Full reasoning, guideline sources & artwork checks</summary>'+slideReasoning(currentJob,route,p)+reasonCard('The concept',`<p>${esc(r.conceptExplanation?.idea||'No concept explanation was saved.')}</p><p>${esc(r.conceptExplanation?.takeaway||'')}</p><p>${esc(r.conceptExplanation?.rationale||'')}</p>`)+reasonCard('Why this placement',`<p>${esc(p.guidance||p.name)}</p><p>${esc(p.dimensions?p.dimensions.width+' × '+p.dimensions.height+' pixels':'Dimensions depend on the placement contract.')}</p>${a?.viewingSize?`<p>${esc(typeof a.viewingSize==='string'?a.viewingSize:a.viewingSize.direction||'No viewing-size rationale was saved.')}</p>`:''}<p class="help">Publisher acceptance and campaign performance are not established by the artwork score.</p>`)+reasonCard('Visual hierarchy & layout',`<span class="pill">Intended design choices</span>${a?.hierarchy?`<ol>${a.hierarchy.map(x=>`<li>${esc(x.replace(/^\d+\.\s*/,''))}</li>`).join('')}</ol>`:''}<p>${esc(r.compositionRationale?.text||a?.rationale||a?.composition||'No layout rationale was saved.')}</p><p class="help">${esc(r.compositionRationale?.limits||'These are the intended choices. The observed execution is recorded in the checks below.')}</p>`)+protectedProductReasoning(u)+brandGuidelineReasoning(u)+readingReviewHtml(u)+reasonCard('Guidelines & source basis',relevant.map(g=>`<div class="review-check"><b>${esc(g.text)}</b><p class="help">Source: ${esc((g.sourceIds||[]).map(id=>id==='user-brief'?'Your campaign brief':projectDetails.sources.find(s=>s.id===id)?.label||id).join(' · '))}</p></div>`).join('')+`<p class="help">These are the saved requirements used for this project. A requirement is not proof that the exported artwork passed it.</p>${(guardian?.unknowns||[]).length?`<details><summary>Missing guidance & assumptions</summary>${guardian.unknowns.map(x=>`<p>${esc(text(x)||JSON.stringify(x))}</p>`).join('')}</details>`:''}`)+reasonCard('Actual artwork checks',`${(review?.criticalChecks||[]).map(c=>`<div class="review-check"><span class="badge ${c.status==='pass'?'':c.status==='fail'?'flagged':'pending'}">${esc(c.status||'Unverified')}</span><b>${esc(c.criterion||c.id)}</b><p>${esc(text(c.evidence)||c.note||c.request||'')}</p></div>`).join('')}${visual.map(q=>`<div class="review-check"><b>${esc(q.criterion.replace(/([A-Z])/g,' $1'))} · ${score(q.score)}/100</b><p>${esc(text(q.evidence))}</p></div>`).join('')}<p class="help">${esc(typeof review?.limits==='string'?review.limits:(review?.limits||[]).map(text).join(' '))}</p><p class="help">${r.qualityVerified?'Score is verified by the saved artwork review.':'Artwork quality remains unverified.'}</p>${r.verificationRecovered?`<p class="help">Checks recovered on the same saved image. <a href="${esc(r.originalReviewUrl)}" target="_blank">Original review ↗</a></p>`:''}${r.supplementalReview?`<p class="help">Additional verification is available; the original delivery flag is retained. <a href="${esc(r.supplementalReview.reportUrl)}" target="_blank">Additional review ↗</a></p>`:''}${r.verificationRetryAvailable?'<button class="secondary" id="retryChecks">Retry checks on this image</button><p class="help">Scoring only, using the remaining review budget. No new image is created.</p>':''}`)+'</details>';if($('#retryChecks'))$('#retryChecks').onclick=async()=>{const button=$('#retryChecks');button.disabled=true;button.textContent='Checking the saved image…';try{await post('/creative-ai/api/jobs/'+currentJob.id+'/retry-checks',{route,placementId});currentJob=await api('/creative-ai/api/jobs/'+currentJob.id);projectDetails=null;await openDetail(key);}catch(e){showError($('#detailError'),e);button.disabled=false;button.textContent='Retry checks on this image';}};}catch(e){showError($('#detailError'),e);$('#detailReasoning').innerHTML=reasonCard('Saved concept',`<p>${esc(r.conceptExplanation?.idea)}</p><p>${esc(r.compositionRationale?.text)}</p>`);}}
