$('#savedButton').onclick=async()=>{const epoch=++navigationEpoch;clearTimeout(timer);detailKey=null;screen('saved');history.replaceState(null,'','/creative-ai?saved=1'+(activeBrand?'&brand='+activeBrand.id:''));$('#savedList').innerHTML='<p>Loading saved projects…</p>';try{const [jobs,drafts]=await Promise.all([api('/creative-ai/api/jobs'),api('/creative-ai/api/research')]);if(epoch!==navigationEpoch)return;rememberJobs(jobs);$('#savedCount').textContent=jobs.filter(j=>!activeBrand||belongs(j,activeBrand)).length;$('#savedList').innerHTML=jobs.filter(j=>!activeBrand||belongs(j,activeBrand)).map(j=>`<a class="saved-row" href="/creative-ai?job=${esc(j.id)}"><div><b>${esc(new URL(j.brandUrl).hostname)}</b><small>${new Date(j.createdAt).toLocaleString()}</small></div><span>${esc(j.status)} · ${j.outputs} images →</span></a>`).join('')||'<div class="card"><h2>Your projects will appear here</h2><p>Choose Duroflex or Sleepyhead and start a brief.</p></div>';if(drafts.filter(r=>!activeBrand||r.brandId===activeBrand.id).length)$('#savedList').innerHTML+='<h2 style="margin-top:35px">Brand research drafts</h2>'+drafts.filter(r=>!activeBrand||r.brandId===activeBrand.id).map(r=>`<a class="saved-row" href="/creative-ai?research=${esc(r.id)}"><div><b>${esc(new URL(r.brandUrl).hostname)}</b><small>${new Date(r.createdAt).toLocaleString()}</small></div><span>${esc(r.status)} · Brand context →</span></a>`).join('');}catch(e){$('#savedList').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};
function rememberJobs(jobs){savedTotal=jobs.length;brandProjectCounts=Object.fromEntries(brandList.map(b=>[b.id,jobs.filter(j=>belongs(j,b)).length]));}
