async function loadBrands(){brandList=await api('/creative-ai/api/brands');renderBrandNav();}
function renderBrandNav(){const logo=brandHeaderLogos[activeBrand?.id];$('#brandHeaderLogo').hidden=!logo;if(logo){$('#brandHeaderLogo').src=logo.imageData;$('#brandHeaderLogo').alt=logo.name+' logo';}else{$('#brandHeaderLogo').removeAttribute('src');$('#brandHeaderLogo').alt='';}if($('#brandToggle'))$('#brandToggle').innerHTML=brandList.map(b=>`<button type="button" data-switch-brand="${esc(b.id)}" aria-pressed="${activeBrand?.id===b.id}">${esc(b.name)}</button>`).join('');document.title=(activeBrand?.name||'Duroflex')+' Studio · Creative AI';$('#savedCount').textContent=activeBrand?(activeBrand.projects?.length??brandProjectCounts[activeBrand.id]??0):savedTotal;$('#brandNav').innerHTML=brandList.map(b=>`<button class="nav-button ${activeBrand?.id===b.id?'active':''}" data-brand="${esc(b.id)}">${esc(b.name)}</button>`).join('');}
