async function showBrands(){const epoch=++navigationEpoch;clearTimeout(timer);detailKey=null;activeBrand=null;await loadBrands();if(epoch!==navigationEpoch)return;screen('brandsScreen');history.replaceState(null,'','/creative-ai?brands=1');$('#brandsList').innerHTML=brandList.map(b=>`<a class="card" href="/creative-ai?brand=${esc(b.id)}"><span class="brand-icon">${esc(b.name[0])}</span><h2>${esc(b.name)}</h2><p>${esc(new URL(b.brandUrl).hostname)}</p><p>${b.documents.length} documents · ${b.latestResearchId?'Knowledge ready':'Knowledge needs updating'}</p><span class="help">Open workspace →</span></a>`).join('')||'<div class="card"><h2>Brand workspaces unavailable</h2><p>Duroflex and Sleepyhead need to be restored in the studio configuration.</p></div>';}
