async function openBrand(id){const epoch=++navigationEpoch;clearTimeout(timer);detailKey=null;const brand=await api('/creative-ai/api/brands/'+encodeURIComponent(id));if(epoch!==navigationEpoch)return;activeBrand=brand;$('#brandDocumentForm').reset();$('#assetUploadProgress').textContent='';researchSession=null;currentJob=null;projectDetails=null;draftAssets=[];selected=new Set();$('#briefForm').reset();renderBrandNav();screen('brandWorkspace');history.replaceState(null,'','/creative-ai?brand='+encodeURIComponent(id)+'&tab='+encodeURIComponent(brandTab));$('#brandWorkspaceTitle').textContent=activeBrand.name;$('#brandWorkspaceUrl').textContent=activeBrand.brandUrl;$('#brandWorkspaceError').hidden=true;await renderBrandTab(brandTab);window.scrollTo(0,0);}
const documentUnit=d=>d?.format==='pdf'?'page':['docx','txt','md','csv'].includes(d?.format)?'section':'slide';
const citations=refs=>`<div class="brand-citations">${(refs||[]).map(r=>`<button data-document="${esc(r.documentId)}" data-slide="${r.slide}">${esc(activeBrand.documents.find(d=>d.id===r.documentId)?.kind||'Source')} · ${documentUnit(activeBrand.documents.find(d=>d.id===r.documentId))} ${r.slide}</button>`).join('')}</div>`;
async function renderBrandTab(tab){const tabEpoch=++brandTabEpoch,epoch=navigationEpoch;brandTab=tab;document.querySelectorAll('[data-brand-tab]').forEach(b=>b.classList.toggle('active',b.dataset.brandTab===tab));$('#brandDocumentForm').hidden=tab!=='guidelines';const b=activeBrand,profile=b.profile;let html='';if(tab==='overview'){html=`<div class="brand-configuration"><div class="card"><span class="eyebrow">BRAND CONFIGURATION</span><h2>${esc(profile?.status||(b.documents.length?'Brand guidance saved':'Build your brand context'))}</h2><p>${esc(profile?.basis||(b.documents.length?'Source documents are saved. Refresh website research to combine them with current product evidence.':'Add your source documents and research the official website to build the brand context.'))}</p><div class="brand-point"><b>Source documents</b><p>${b.documents.length} ${b.documents.length===1?'document':'documents'} · ${b.documents.reduce((n,d)=>n+d.slideCount,0)} ${b.documents.every(d=>d.format==='pdf')?'pages':b.documents.every(d=>d.format!=='pdf')?'slides':'pages / slides'} indexed</p></div><div class="brand-point"><b>Website research</b><p>${b.latestResearchId?'Saved and available for the next brief.':'Research the current website before creating images.'}</p><button class="secondary" data-research-brand>Update brand knowledge ↗</button></div><div class="brand-point"><b>Test defaults</b><p>${esc(b.defaults.language)} · ${esc(b.defaults.region||'Region set in each brief')} · Two creative directions</p><p class="help">One correction cycle per direction and format. Image formats remain subject to availability.</p></div></div><div class="card"><span class="eyebrow">WHAT THE AGENTS WILL USE</span><h2>Research and guidance stay with ${esc(b.name)}</h2>${(profile?.sections||[]).map(s=>`<div class="brand-point"><b>${esc(s.title)}</b><p>${esc(s.summary)}</p></div>`).join('')||(b.documents.length?'<p>Your saved documents will be included in this brand’s next research run.</p>':'<p>Add brand books, research, guidelines and examples in the Asset library.</p>')}</div><div class="card wide-card"><h2>Source precedence</h2>${(profile?.sourcePrecedence||['Supplied brand guidance sets intent. Current official sources establish available products. Campaign instructions define each assignment.']).map(t=>`<p>${esc(t)}</p>`).join('')}</div></div>`;}else if(tab==='guidelines'){html=await assetLibraryHtml(b);}else if(tab==='products'){html=await productLibraryHtml(b);}else if(tab==='memory'){const m=await api('/creative-ai/api/brands/'+b.id+'/memory');html=`<div class="card training-assets-link"><div><h2>Train with brand assets</h2><p>Brand books, visual guides and sample creatives stay in ${esc(b.name)}’s organized library.</p></div><button class="secondary" data-add-training-assets>Add training assets →</button></div>`+trainingForm(b)+`<div class="card"><h2>${esc(b.name)} preferences</h2><p>Memory version ${m.revision}. Use the named-brand training form to save a preference. Preferences inform future briefs alongside this brand’s rules and verified product facts.</p><p class="help">This is reusable brand memory, not model weight training. Disabling a preference affects future jobs; saved jobs retain the version they used.</p>${m.preferences.map(p=>`<div class="brand-point"><b>${esc(p.text)}</b><p>${esc(p.scope)} · Version ${p.version} · ${p.active?'Active':'Disabled'}</p><p class="help">${esc(p.productUrl||'All products')}${p.placementId?' · '+esc(p.placementId):''}</p>${p.provenance.kind==='named-brand-training'?`<p class="help">Training explicitly saved for ${esc(p.provenance.brandName)} · ${esc(p.createdAt)}</p>`:`<p class="help">From ${esc(p.provenance.route)} image version ${p.provenance.artifactVersion} · ${esc(p.provenance.reviewStatus)} · ${esc(p.createdAt)}</p><a href="${esc(p.provenance.imageUrl)}" target="_blank">Exact source image ↗</a> · <a href="${esc(p.provenance.reviewUrl)}" target="_blank">Saved review ↗</a>`}${p.active?`<button class="secondary" data-disable-preference="${esc(p.id)}" data-version="${p.version}">Disable preference</button>`:''}</div>`).join('')||'<p>No reusable preferences saved yet.</p>'}<p>${m.feedback.length} feedback notes saved · ${m.feedback.filter(f=>f.evaluatedExample).length} liked examples with passing saved reviews. Historical flags remain unchanged.</p></div>`;}else if(tab==='projects'){html=b.projects.map(j=>`<a class="saved-row" href="/creative-ai?job=${esc(j.id)}&brand=${esc(b.id)}"><div><b>${esc(b.name)} creative project</b><small>${new Date(j.createdAt).toLocaleString()}${j.priorConfiguration?' · Earlier test: before the supplied decks':''}</small></div><span>${esc(j.status)} · ${j.outputs} images →</span></a>`).join('')||'<div class="card"><h2>Your brand projects will appear here</h2><p>Start a brief once your research is ready.</p></div>';}else{html='<div class="card"><h2>Website research</h2><p>Official sources, assets and access gaps for this brand.</p><button class="primary" data-research-brand>Update brand knowledge →</button></div>';if(b.latestResearchId){const r=await api('/creative-ai/api/research/'+b.latestResearchId);researchSession=r;html=brandHtml(r.dossier);html+='<div class="bottom-actions"><span class="help">Research collected '+esc(new Date(r.dossier.completedAt).toLocaleString())+'</span><button class="secondary" data-research-brand>Update brand knowledge ↗</button></div>';}}if(epoch!==navigationEpoch||tabEpoch!==brandTabEpoch||activeBrand?.id!==b.id||brandTab!==tab)return;if(!$('#brandWorkspace').hidden)history.replaceState(null,'','/creative-ai?brand='+encodeURIComponent(b.id)+'&tab='+encodeURIComponent(tab));$('#brandWorkspaceContent').innerHTML=html;if(tab==='memory')bindTrainingForm();if(tab==='guidelines')bindAssetLibrary(b);if(tab==='products')bindProductLibrary(b);}
$('#brandTabs').onclick=e=>{if(e.target.dataset.brandTab)renderBrandTab(e.target.dataset.brandTab).catch(e=>showError($('#brandWorkspaceError'),e));};
async function researchBrand(){const r=await post('/creative-ai/api/research',{brandId:activeBrand.id,brandUrl:activeBrand.brandUrl,requestKey:crypto.randomUUID()});openResearch(r.id);}
$('#brandWorkspaceContent').onclick=async e=>{const doc=e.target.closest('[data-document]');try{if(e.target.closest('[data-add-training-assets]')){await renderBrandTab('guidelines');$('#brandDocumentForm').scrollIntoView({behavior:'smooth',block:'start'});}else if(e.target.closest('[data-disable-preference]')){const button=e.target.closest('[data-disable-preference]');button.disabled=true;await post('/creative-ai/api/brands/'+activeBrand.id+'/memory/'+button.dataset.disablePreference+'/deactivate',{version:Number(button.dataset.version)});await renderBrandTab('memory');}else if(doc)await openDocument(doc.dataset.document,doc.dataset.slide);else if(e.target.closest('[data-research-brand]')){const button=e.target.closest('[data-research-brand]');button.disabled=true;await researchBrand();}}catch(e){showError($('#brandWorkspaceError'),e);e.target.disabled=false;}};
async function startBrandBrief(){const epoch=++navigationEpoch,id=activeBrand.id,brand=await api('/creative-ai/api/brands/'+id);if(epoch!==navigationEpoch||activeBrand?.id!==id)return false;activeBrand=brand;if(brand.latestResearchId){const r=await api('/creative-ai/api/research/'+brand.latestResearchId);if(epoch!==navigationEpoch||activeBrand?.id!==id)return false;if(r.brandId!==id||!r.dossier)throw Error('This brand’s current research is not ready. Update brand knowledge before starting a brief.');renderResearch(r);const opened=await openBrief();if(!opened)return false;if(!sessionStorage.getItem('studio-brief-'+researchSession.id)){selected=new Set((activeBrand.defaults.placementIds||[]).filter(id=>config.placements.find(p=>p.id===id)?.supported));placements();saveDraft();}return true;}else{brandTab='guidelines';await openBrand(id);showError($('#brandWorkspaceError'),Error('Update this brand’s knowledge to include its latest assets before starting a brief.'));return false;}}
$('#brandNewBrief').onclick=()=>startBrandBrief().catch(e=>showError($('#brandWorkspaceError'),e));
$('#brandDocumentForm').onsubmit=async e=>{e.preventDefault();const uploadEpoch=navigationEpoch,files=[...$('#brandDocumentFile').files],button=$('#uploadDocumentButton'),error=$('#brandDocumentForm .form-error'),target=brandList.find(b=>b.name===$('#assetBrandName').value),category=$('#assetCategory').value,draft=$('#documentDraft').checked,note=$('#assetNotes').value;button.disabled=true;error.hidden=true;let saved=0;try{if(!target)throw Error('Choose Duroflex or Sleepyhead by name.');if(!files.length||files.length>20)throw Error('Choose between 1 and 20 files.');for(const file of files){if(navigationEpoch===uploadEpoch)$('#assetUploadProgress').textContent='Saving to '+target.name+' · '+(saved+1)+' / '+files.length+' · '+file.name;await api('/creative-ai/api/brands/'+target.id+'/assets',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Brand-Name':target.name,'X-File-Name':encodeURIComponent(file.name),'X-Asset-Category':category,'X-Asset-Draft':String(draft),'X-Asset-Note':encodeURIComponent(note)},body:file});saved++;}if(navigationEpoch!==uploadEpoch)return;$('#brandDocumentForm').reset();brandTab='guidelines';await openBrand(target.id);$('#assetUploadProgress').textContent=saved+' files saved to '+target.name+'. Document and image changes need a research refresh before the next brief.';}catch(e){if(navigationEpoch!==uploadEpoch)return;showError(error,e);$('#assetUploadProgress').textContent=saved+' / '+files.length+' files saved. Successful files are retained; retry the remaining files.';}finally{button.disabled=false;}};
async function openDocument(id,slide){const epoch=++navigationEpoch,brandId=activeBrand.id,doc=await api('/creative-ai/api/brands/'+brandId+'/documents/'+encodeURIComponent(id));if(epoch!==navigationEpoch||activeBrand?.id!==brandId)return;currentDocument=doc;screen('documentScreen');const unit=documentUnit(currentDocument);$('#documentTitle').textContent=currentDocument.name;$('#documentMeta').textContent=currentDocument.slideCount+' '+unit+'s · '+(currentDocument.draft?'Supplied draft':'Supplied document')+' · '+(currentDocument.format==='pdf'?currentDocument.nativeTextPages+'/'+currentDocument.pageCount+' pages with native text; full page previews saved':'Text indexed; inspect coverage notes');$('#documentDownload').href='/creative-ai/api/brands/'+activeBrand.id+'/documents/'+id+'/original';$('#documentSearch').placeholder='Search all indexed '+unit+'s…';$('#documentSearch').setAttribute('aria-label','Search document '+unit+'s');$('#documentSearch').value=slide?unit+' '+slide:'';renderDocument();window.scrollTo(0,0);}
function renderDocument(){const unit=documentUnit(currentDocument),term=$('#documentSearch').value.toLowerCase().trim(),match=/^(?:slide|page|section) (\d+)$/.exec(term);const rows=currentDocument.slides.filter(s=>match?s.slide===Number(match[1]):!term||(s.text+' '+s.notes).toLowerCase().includes(term));$('#documentSlides').innerHTML=rows.map(s=>`<article class="card"><div class="section-title"><h2>${unit==='page'?'Page':unit==='section'?'Section':'Slide'} ${s.slide}</h2><span class="pill">${s.hidden?'Hidden working slide · ':''}${s.text?'Text indexed':s.hasImages?'Visual content; no native text':'No indexed text'}</span></div>${currentDocument.visuals.some(v=>v.slide===s.slide)?`<img src="/creative-ai/api/brands/${activeBrand.id}/documents/${currentDocument.id}/slide-${s.slide}.jpg" alt="Actual supplied ${unit} ${s.slide}" loading="lazy">`:''}<pre>${esc(s.text||s.textNote||'No native text. Inspect the actual source document; no guidance has been inferred.')}</pre>${s.notes?`<details><summary>Speaker notes</summary><pre>${esc(s.notes)}</pre></details>`:''}</article>`).join('')||'<p>No matching '+unit+' text.</p>';}
$('#documentSearch').oninput=renderDocument;$('#documentBack').onclick=()=>{brandTab='guidelines';openBrand(activeBrand.id);};

(async()=>{try{workspaceConfig=await api('/creative-ai/api/workspace');config=await api('/creative-ai/api/config');$('#creativeType').innerHTML=config.creativeTypes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');await loadBrands();placements();rememberJobs(await api('/creative-ai/api/jobs'));renderBrandNav();const params=new URLSearchParams(location.search);if(['overview','research','guidelines','products','projects','memory'].includes(params.get('tab')))brandTab=params.get('tab');if(params.get('brand')){activeBrand=await api('/creative-ai/api/brands/'+params.get('brand'));renderBrandNav();}if(location.pathname==='/creative-ai/costs'||params.has('costs')){await openCosts();}else if(params.get('job')){const j=await api('/creative-ai/api/jobs/'+encodeURIComponent(params.get('job')));render(j);if(params.get('image'))await openDetail(params.get('image'));else if(['queued','running'].includes(j.status))poll(j.id);}else if(params.get('research')){await pollResearch(params.get('research'));if(params.get('step')==='brief')await openBrief();}else if(params.get('saved'))$('#savedButton').click();else if(params.get('brand')){await openBrand(params.get('brand'));if(brandTab==='products'&&params.get('product'))await showProductProfile(activeBrand,params.get('product'));}else if(params.get('brands'))await showBrands();else if(brandList.length)await openBrand(workspaceConfig.defaultBrandId);else await showBrands();}catch(e){showError($('#startupError'),e);}})();

function imageReactionKey(jobId,result){return JSON.stringify([jobId,result.route,result.placementId,result.imageUrl]);}
function feedbackRatingLabel(rating){return rating==='like'?'Thumbs up':rating==='change'?'Thumbs down':'Note';}
function imageReactionHtml(job,result){const key=imageReactionKey(job.id,result),state=imageReactions.get(key)||{};return `<div class="image-reactions" data-reaction-key="${esc(key)}" role="group" aria-label="Feedback for ${esc(result.route+' '+result.placementId)}"><div class="reaction-buttons"><button type="button" class="secondary reaction-button" data-image-rating="like" aria-label="Thumbs up" aria-pressed="${state.rating==='like'}" ${state.pending?'disabled':''}>👍 <span>Like</span></button><button type="button" class="secondary reaction-button" data-image-rating="change" aria-label="Thumbs down" aria-pressed="${state.rating==='change'}" ${state.pending?'disabled':''}>👎 <span>Dislike</span></button></div><p class="reaction-status help" role="status">${esc(state.message||(state.rating?'Saved · '+feedbackRatingLabel(state.rating):'Saved feedback only · not used for learning'))}</p></div>`;}
function updateImageReaction(key){const state=imageReactions.get(key)||{};document.querySelectorAll('[data-reaction-key]').forEach(node=>{if(node.dataset.reactionKey!==key)return;node.querySelectorAll('[data-image-rating]').forEach(button=>{button.disabled=!!state.pending;button.setAttribute('aria-pressed',String(state.rating===button.dataset.imageRating));});node.querySelector('.reaction-status').textContent=state.message||(state.rating?'Saved · '+feedbackRatingLabel(state.rating):'Saved feedback only · not used for learning');});}
function seedImageReactions(job,notes){for(const result of job.results||[]){if(!result.imageUrl)continue;const key=imageReactionKey(job.id,result),state=imageReactions.get(key)||{},latest=notes.filter(n=>n.imageUrl===result.imageUrl&&n.route===result.route&&n.placementId===result.placementId&&['like','change'].includes(n.rating)).at(-1);if(!state.pending&&!state.rating&&latest)imageReactions.set(key,{rating:latest.rating});updateImageReaction(key);}}
async function loadImageReactions(job){if(!job.results?.some(r=>r.imageUrl)||reactionLoads.has(job.id))return;const pending=api('/creative-ai/api/jobs/'+encodeURIComponent(job.id)+'/feedback');reactionLoads.set(job.id,pending);try{seedImageReactions(job,await pending);}catch{reactionLoads.delete(job.id);}}
async function saveImageReaction(button){const job=currentJob,container=button.closest('[data-reaction-key]'),key=container?.dataset.reactionKey,result=job?.results.find(r=>imageReactionKey(job.id,r)===key),rating=button.dataset.imageRating;if(!result||!['like','change'].includes(rating))return;const previous=imageReactions.get(key)||{};if(previous.pending||previous.rating===rating)return;imageReactions.set(key,{...previous,pending:true,message:'Saving…'});updateImageReaction(key);try{const artifact=await api('/creative-ai/api/jobs/'+encodeURIComponent(job.id)+'/feedback-artifact?route='+encodeURIComponent(result.route)+'&placementId='+encodeURIComponent(result.placementId));if(artifact.imageUrl!==result.imageUrl)throw Error('This image version changed. Reopen it before saving feedback.');const saved=await post('/creative-ai/api/jobs/'+encodeURIComponent(job.id)+'/feedback',{brandName:brandList.find(b=>b.id===artifact.brandId)?.name,route:result.route,placementId:result.placementId,imageUrl:artifact.imageUrl,artifactHash:artifact.artifactHash,rating,text:'',captureMode:'stored-only'});imageReactions.set(key,{rating:saved.feedback.rating,message:'Saved · '+feedbackRatingLabel(saved.feedback.rating)});if(currentJob?.id===job.id&&detailKey===result.route+'|'+result.placementId){$('#savedFeedbackNotes').insertAdjacentHTML('beforeend',`<div class="brand-point"><b>${esc(feedbackRatingLabel(saved.feedback.rating))}</b><small>${esc(saved.feedback.createdAt)}</small></div>`);const summary=$('#feedbackForm').querySelector('summary');summary.textContent='Saved feedback ('+(Number(/\((\d+)\)/.exec(summary.textContent)?.[1]||0)+1)+')';}}catch(error){imageReactions.set(key,{...previous,message:'Could not save: '+error.message});}finally{updateImageReaction(key);}}
async function loadImageFeedback(key,result){
 if(!result.imageUrl)return;
 const [route,placementId]=key.split('|'),job=currentJob,jobId=job.id,epoch=navigationEpoch;
 const [artifact,notes]=await Promise.all([api('/creative-ai/api/jobs/'+jobId+'/feedback-artifact?route='+encodeURIComponent(route)+'&placementId='+encodeURIComponent(placementId)),api('/creative-ai/api/jobs/'+jobId+'/feedback')]);
 if(epoch!==navigationEpoch||currentJob?.id!==jobId||detailKey!==key)return;
 seedImageReactions(job,notes);
 $('#imageFeedback').innerHTML=`<form id="feedbackForm" class="card"><h2>What do you think?</h2>${imageReactionHtml(job,result)}<p class="help">Saved to ${esc(brandList.find(b=>b.id===artifact.brandId)?.name)} for this image version. Feedback is stored only and is not used for learning or tuning.</p><label>Optional feedback<textarea name="feedback" maxlength="2000" placeholder="Tell us what works or what you would change."></textarea></label><div class="form-error error" hidden></div><button type="submit" class="primary">Save note</button><p id="feedbackSaved" role="status"></p><details><summary>Saved feedback (${notes.filter(n=>n.artifactHash===artifact.artifactHash).length})</summary><div id="savedFeedbackNotes">${notes.filter(n=>n.artifactHash===artifact.artifactHash).map(n=>`<div class="brand-point"><b>${esc(feedbackRatingLabel(n.rating))}</b>${n.text?`<p>${esc(n.text)}</p>`:''}<small>${esc(n.createdAt)}</small></div>`).join('')}</div></details></form>`;
 const form=$('#feedbackForm');form.onclick=e=>{const button=e.target.closest('[data-image-rating]');if(button)saveImageReaction(button);};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;form.querySelector('.form-error').hidden=true;try{if(!form.elements.feedback.value.trim())throw Error('Add a note, or use the thumbs above.');await post('/creative-ai/api/jobs/'+artifact.jobId+'/feedback',{brandName:brandList.find(b=>b.id===artifact.brandId)?.name,route,placementId,imageUrl:artifact.imageUrl,artifactHash:artifact.artifactHash,rating:imageReactions.get(imageReactionKey(jobId,result))?.rating||'neutral',text:form.elements.feedback.value,captureMode:'stored-only'});if(epoch===navigationEpoch&&currentJob?.id===jobId&&detailKey===key){await loadImageFeedback(key,result);$('#feedbackSaved').textContent='Note saved. Not used for learning.';}}catch(e){if(epoch===navigationEpoch)showError(form.querySelector('.form-error'),e);}finally{button.disabled=false;}};
}

function trainingForm(brand){return `<form id="trainingForm" class="card training-form"><h2>Train for a named brand</h2><p>Choose the brand and describe a creative preference to reuse in future briefs.</p><label>Brand name<select name="brandName">${brandList.map(b=>`<option value="${esc(b.name)}" ${b.id===brand.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><p class="brand-target" id="trainingTarget">Save to ${esc(brand.name)} only</p><label>What should this brand remember?<textarea name="preference" required maxlength="1000" placeholder="For example: Keep headlines concise and give the product more breathing room."></textarea></label><p class="help">Creative preferences stay separate from verified product facts and supplied brand guidance.</p><div class="form-error error" hidden></div><button class="primary">Save brand training</button><p id="trainingSaved" role="status"></p></form>`;}
function bindTrainingForm(){const form=$('#trainingForm');form.elements.brandName.onchange=()=>{$('#trainingTarget').textContent='Save to '+form.elements.brandName.value+' only';};form.onsubmit=async e=>{e.preventDefault();const epoch=navigationEpoch,button=form.querySelector('button');button.disabled=true;form.querySelector('.form-error').hidden=true;try{const saved=await post('/creative-ai/api/training',{brandName:form.elements.brandName.value,preference:form.elements.preference.value});if(epoch!==navigationEpoch||!form.isConnected)return;brandTab='memory';await openBrand(saved.preference.brandId);$('#trainingSaved').textContent='Saved to '+saved.preference.provenance.brandName+' · memory version '+saved.revision;}catch(e){showError(form.querySelector('.form-error'),e);}finally{button.disabled=false;}};}

let costData=null,costRowsShown=50,costTimer=null;
const inr=v=>v===null||v===undefined?'Unknown':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:2,maximumFractionDigits:2}).format(v);
async function openCosts(){++navigationEpoch;clearTimeout(timer);clearTimeout(costTimer);detailKey=null;history.replaceState(null,'','/creative-ai/costs');screen('costScreen');await refreshCosts();}
$('#costsButton').onclick=openCosts;
async function refreshCosts(){if($('#costScreen').hidden)return;const epoch=navigationEpoch;try{const d=await api('/creative-ai/api/costs');if(epoch!==navigationEpoch||$('#costScreen').hidden)return;costData=d;$('#costError').hidden=true;if(!$('#costBrand').dataset.ready){$('#costBrand').insertAdjacentHTML('beforeend',d.brands.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join(''));$('#costPurpose').insertAdjacentHTML('beforeend',d.purposes.map(p=>`<option>${esc(p)}</option>`).join(''));const f=$('#costEntryForm');f.elements.brandId.innerHTML='<option value="shared">Shared system</option>'+d.brands.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');for(const [key,list] of [['category',d.categories],['purpose',d.purposes]])f.elements[key].innerHTML=list.map(v=>`<option>${esc(v)}</option>`).join('');f.elements.date.value=new Date().toLocaleDateString('en-CA');$('#costBrand').dataset.ready='1';}renderCosts();}catch(e){showError($('#costError'),e);$('#costFreshness').textContent='Updates paused · last saved view may be stale. Retrying in 5 seconds.';}finally{if(!$('#costScreen').hidden)costTimer=setTimeout(refreshCosts,5000);}}
function filteredCosts(){const now=new Date(),period=$('#costPeriod').value,begin=period==='today'?new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime():period==='all'?0:Date.now()-Number(period)*86400000;return costData.entries.filter(r=>($('#costBrand').value==='all'||r.brandId===$('#costBrand').value)&&($('#costOrigin').value==='All history'||r.origin===$('#costOrigin').value)&&($('#costPurpose').value==='all'||r.purpose===$('#costPurpose').value)&&new Date(r.timestamp).getTime()>=begin);}
function renderCosts(){const d=costData;if(!$('#costOrigin').dataset.ready){if(!d.dedicatedSince)$('#costOrigin').value='All history';$('#costOrigin').dataset.ready='1';}$('#costCurrencyNote').innerHTML=d.fx? 'INR estimates · USD 1 = '+esc(d.fx.usdToInr)+' INR · reference '+esc(d.fx.rateDate)+' · <a href="'+esc(d.fx.source)+'" target="_blank" rel="noopener">Exchange-rate source ↗</a> · Actual card charges may differ.':'INR conversion unavailable: add a dated exchange-rate source to the local ledger settings.';const rows=filteredCosts(),sum=key=>rows.reduce((n,r)=>n+(r[key]??0),0),known=rows.some(r=>r.actualInr!=null||r.estimatedInr!=null)?rows.reduce((n,r)=>n+(r.actualInr??r.estimatedInr??0),0):null,unknown=rows.filter(r=>r.actualInr==null&&r.estimatedInr==null).length;$('#costFreshness').textContent='Live · refreshes every 5 seconds · checked '+new Date(d.generatedAt).toLocaleTimeString()+' · '+(d.sync?.lastSyncedAt?'Sheet last synced '+new Date(d.sync.lastSyncedAt).toLocaleString():d.sync?'Sheet not yet synced':'Local ledger saved · Sheet sync not configured')+(d.sync?.cadence?' · '+d.sync.cadence:'');const link=$('#costSheetLink');link.hidden=!d.sync?.url;if(d.sync?.url)link.href=d.sync.url;$('#costCards').innerHTML=[['Known total',inr(known),'Actual when available, otherwise estimate'],['Usage estimates',rows.some(r=>r.estimatedInr!=null)?inr(sum('estimatedInr')):'Unknown','Based on recorded usage + manual estimates'],['Actual recorded',rows.some(r=>r.actualInr!=null)?inr(sum('actualInr')):'Not entered','Billed amounts added separately'],['Unmetered costs',unknown?String(unknown)+' unknown':'Not captured','Developer compute, hosting & external billing']].map(([label,value,note])=>`<article class="card"><span class="eyebrow">${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('');const cat=d.categories.map(category=>({category,rows:rows.filter(r=>r.category===category)}));$('#costBreakdown').innerHTML=cat.map(c=>{const amount=c.rows.reduce((n,r)=>n+(r.actualInr??r.estimatedInr??0),0);return `<div class="cost-category"><div><b>${esc(c.category)}</b><strong>${c.rows.some(r=>r.actualInr!=null||r.estimatedInr!=null)?inr(amount):c.rows.length?'Unknown':'No recorded costs'}</strong></div><div class="cost-bar"><span style="width:${known?amount/known*100:0}%"></span></div><small>${c.rows.filter(r=>r.source==='Provider receipt').length} recorded calls · ${c.rows.filter(r=>r.actualInr==null&&r.estimatedInr==null).length} unknown amounts</small></div>`;}).join('');$('#costActive').innerHTML=d.active.filter(r=>$('#costBrand').value==='all'||d.brands.find(b=>b.name===r.brand)?.id===$('#costBrand').value).map(r=>`<div class="brand-point"><b>${esc(r.brand)} · ${esc(r.kind)}</b><p>${esc(r.status)} · ${esc(r.stage)}</p><small>Reserved allowance ${inr(r.reservedInr)} · not actual spend</small></div>`).join('')||'<p class="help">No active jobs in this brand view. New calls will appear here as they are recorded.</p>';$('#costPurposeBreakdown').innerHTML=d.purposes.map(p=>`<div class="cost-purpose"><span>${esc(p)}</span><b>${rows.some(r=>r.purpose===p&&(r.actualInr!=null||r.estimatedInr!=null))?inr(rows.filter(r=>r.purpose===p).reduce((n,r)=>n+(r.actualInr??r.estimatedInr??0),0)):'Not recorded'}</b></div>`).join('');const daily=new Map();for(const r of rows){if(r.actualInr==null&&r.estimatedInr==null)continue;const day=r.timestamp.slice(0,10);daily.set(day,(daily.get(day)||0)+(r.actualInr??r.estimatedInr??0));}const days=[...daily].sort().slice(-30),max=Math.max(0,...days.map(x=>x[1]));$('#costTimeline').innerHTML=days.map(([day,v])=>`<div class="cost-day"><span>${esc(day)}</span><div class="cost-bar"><span style="width:${max?v/max*100:0}%"></span></div><b>${inr(v)}</b></div>`).join('')||'<p class="help">No recorded amounts for this period.</p>';$('#costCoverage').innerHTML=d.coverage.map(v=>`<li>${esc(v)}</li>`).join('')+d.warnings.map(v=>`<li>${esc(v)}</li>`).join('');$('#costAudit').textContent=d.deduplicatedCopies+' copied receipts removed across saved sessions. '+d.unreceiptedReservationOccurrences+' reservation occurrences have no matching receipt count (may include copied history; not unique charges). '+(d.dedicatedSince?'Dedicated studio started '+new Date(d.dedicatedSince).toLocaleString()+'.':'Studio migration date unavailable; historical receipt origins are unknown.');renderCostLedger(rows);}
function renderCostLedger(rows=filteredCosts()){const term=$('#costSearch').value.trim().toLowerCase(),filtered=rows.filter(r=>[r.model,r.sourceId,r.notes,r.brand,r.purpose,r.id].join(' ').toLowerCase().includes(term));$('#costLedgerCount').textContent=filtered.length+' entries · showing '+Math.min(costRowsShown,filtered.length);$('#costLedger').innerHTML=filtered.slice(0,costRowsShown).map(r=>`<tr><td>${esc(new Date(r.timestamp).toLocaleString())}<small>${esc(r.dateBasis)}</small></td><td>${esc(r.brand)}</td><td>${esc(r.category)}<small>${esc(r.purpose)} · ${esc(r.origin)}</small></td><td>${esc(r.model)}<small title="${esc(r.id)}">${esc(r.sourceId)}</small><small>${esc(r.notes)}</small></td><td>${r.estimatedInr==null?'—':inr(r.estimatedInr)}</td><td>${r.actualInr==null?'—':inr(r.actualInr)}</td></tr>`).join('')||'<tr><td colspan="6">No matching entries.</td></tr>';$('#costMore').hidden=filtered.length<=costRowsShown;}
for(const id of ['costBrand','costOrigin','costPurpose','costPeriod'])$('#'+id).onchange=()=>{costRowsShown=50;renderCosts();};$('#costSearch').oninput=()=>{costRowsShown=50;renderCostLedger();};$('#costMore').onclick=()=>{costRowsShown+=50;renderCostLedger();};
const costForm=$('#costEntryForm');costForm.elements.basis.onchange=()=>{const unknown=costForm.elements.basis.value==='unknown';costForm.elements.amount.required=!unknown;costForm.elements.amount.disabled=unknown;};costForm.onsubmit=async e=>{e.preventDefault();const button=costForm.querySelector('button');button.disabled=true;costForm.querySelector('.form-error').hidden=true;try{const values=Object.fromEntries(new FormData(costForm));values.amount=values.basis==='unknown'?null:Number(values.amount);values.currency='INR';await post('/creative-ai/api/costs',values);costForm.elements.reference.value='';costForm.elements.note.value='';costForm.elements.amount.value='';$('#costEntrySaved').textContent='Cost saved in the local ledger.';clearTimeout(costTimer);await refreshCosts();}catch(e){showError(costForm.querySelector('.form-error'),e);}finally{button.disabled=false;}};

let currentAssetLibrary=null,assetFolder='all';
async function assetLibraryHtml(b){const l=await api('/creative-ai/api/brands/'+b.id+'/assets');if(activeBrand?.id!==b.id)return '';currentAssetLibrary=l;assetFolder='all';return `<div class="card asset-library-intro"><div><span class="eyebrow">${esc(b.name.toUpperCase())} / BRAND ASSETS</span><h2>Your brand knowledge, organized</h2><p>Browse source files by folder. Documents and images strengthen the next brand research run; saved projects keep the sources they were created with.</p></div><button class="primary" data-research-brand>Update brand knowledge →</button><p class="help">${l.needsResearchRefresh?'Research refresh needed before starting the next brief.':'Current research is available. New source documents or images will require a refresh.'} Training here means reusable knowledge and references. Large libraries use bounded text excerpts and representative visuals; originals remain available.</p></div><div class="asset-library"><nav id="assetFolders" class="card asset-folders" aria-label="Brand asset folders"></nav><section class="card asset-files-panel"><div class="section-title"><div><span class="eyebrow" id="assetFolderPath"></span><h2 id="assetFolderTitle">All assets</h2></div><span id="assetFolderCount" class="pill"></span></div><label>Search this brand’s assets<input id="assetSearch" type="search" placeholder="Find a file or reference…"></label><div id="assetFilesList"></div></section></div>`;}
function bindAssetLibrary(b){const l=currentAssetLibrary;if(!l||l.brandId!==b.id)return;$('#assetBrandName').innerHTML=brandList.map(br=>`<option ${br.id===b.id?'selected':''}>${esc(br.name)}</option>`).join('');$('#assetCategory').innerHTML=l.folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('');$('#assetBrandName').onchange=()=>$('#assetUploadTarget').textContent='Save to '+$('#assetBrandName').value+' only';$('#assetUploadTarget').textContent='Save to '+b.name+' only';$('#assetFolders').onclick=e=>{const button=e.target.closest('[data-asset-folder]');if(button){assetFolder=button.dataset.assetFolder;if(assetFolder!=='all')$('#assetCategory').value=assetFolder;renderAssetFolders();renderAssetFiles();}};$('#assetSearch').oninput=renderAssetFiles;renderAssetFolders();renderAssetFiles();}
function renderAssetFolders(){const l=currentAssetLibrary,items=[...l.documents,...l.assets];$('#assetFolders').innerHTML=`<button type="button" class="${assetFolder==='all'?'active':''}" data-asset-folder="all"><span>▤ All assets</span><b>${items.length}</b></button>`+l.folders.map(f=>`<button type="button" class="${assetFolder===f.id?'active':''}" data-asset-folder="${esc(f.id)}"><span>▱ ${esc(f.name)}</span><b>${items.filter(a=>a.category===f.id).length}</b></button>`).join('');}
function renderAssetFiles(){const l=currentAssetLibrary,folder=l.folders.find(f=>f.id===assetFolder),term=$('#assetSearch').value.trim().toLowerCase(),rows=[...l.documents,...l.assets].filter(a=>(assetFolder==='all'||a.category===assetFolder)&&[a.name,a.note,a.format].join(' ').toLowerCase().includes(term));$('#assetFolderTitle').textContent=folder?.name||'All assets';$('#assetFolderPath').textContent=l.brandName+' / '+(folder?.name||'All assets');$('#assetFolderCount').textContent=rows.length+' files';$('#assetFilesList').innerHTML=rows.map(a=>{const f=l.folders.find(f=>f.id===a.category),format=a.format||'pptx',base='/creative-ai/api/brands/'+l.brandId+(a.resourceType==='document'?'/documents/':'/assets/')+a.id;return `<article class="asset-file"><div class="asset-file-preview">${a.previewPath?`<img src="${base}/preview" alt="${esc(a.name)}" loading="lazy">`:`<span>${esc(format.toUpperCase())}</span>`}</div><div class="asset-file-copy"><b>${esc(a.name)}</b><small>${esc(f?.name||'Other')} · ${esc(format.toUpperCase())} · ${(a.bytes/1048576).toFixed(2)} MB ${a.draft?'· Draft':''}</small><p>${a.resourceType==='document'?`${a.slideCount} ${documentUnit(a)}s indexed · ${(a.visuals||[]).length} visual references saved. Included in next brand research.`:esc(a.trainingNote)}</p>${a.note?`<p class="help">${esc(a.note)}</p>`:''}<span class="pill">${a.resourceType==='document'?'Indexed source':a.status==='visual-reference'?'Visual reference':a.status==='processed-reference'?'Processed reference':'Stored original'}</span></div><div class="asset-file-actions">${a.resourceType==='document'?`<button class="secondary" data-document="${esc(a.id)}">Inspect →</button>`:a.previewPath?`<a class="secondary" href="${base}/preview" target="_blank" rel="noopener">Preview ↗</a>`:''}<a href="${base}/original" download>Download original ↓</a></div></article>`;}).join('')||'<div class="asset-empty"><h3>This folder is ready for your files</h3><p>Add files below to strengthen this brand’s knowledge.</p></div>';}

let productLibrarySelection=null,productProfileEpoch=0;
function productCreativesHtml(p){const projects=(p.creativeProjects||[]).filter(j=>j.brandId===p.brandId&&j.productId===p.id);if(!projects.length)return '';return `<section class="card"><span class="eyebrow">CREATIVES FOR THIS PRODUCT</span><h3>Generated creatives</h3><p>Saved projects and their artwork stay linked to this SKU. Website source assets are listed separately below.</p>${projects.map(j=>`<a class="saved-row" href="/creative-ai?job=${esc(j.jobId)}"><div><b>${esc(j.title)}</b><small>${esc(j.status)} · ${esc(new Date(j.createdAt).toLocaleString())}</small></div><span>Open project →</span></a>${(j.outputs||[]).filter(o=>o.ready).map(o=>`<p><a href="${esc(o.imageUrl)}" download>${esc(o.route)} · ${esc(o.width)} × ${esc(o.height)} · Download image ↓</a></p>`).join('')}`).join('')}</section>`;}
const productGroupLabel=group=>({'product-images':'Product images',tiles:'Feature tiles','a-plus-content':'A+ content',videos:'Videos','supporting-content':'Supporting content'}[group]||group);
async function productLibraryHtml(b){const products=await api('/creative-ai/api/brands/'+b.id+'/products');return `<div class="card"><span class="eyebrow">${esc(b.name)} PRODUCT KNOWLEDGE</span><h2>Product library</h2><p>Each SKU has its own profile and asset folders. New product URLs in briefs are archived automatically. Save a URL here to collect it before a brief.</p><form id="productCaptureForm"><label>Official product URL<input name="url" type="url" required placeholder="${esc(b.brandUrl)}products/…"></label><div class="bottom-actions"><p class="help">Save to ${esc(b.name)} only. Existing URLs open their saved profile; refresh collects a new snapshot.</p><button class="primary">Save product →</button></div><p id="productCaptureProgress" class="help" aria-live="polite"></p><div class="form-error error" hidden></div></form></div><div class="product-library-grid"><aside class="card"><h3>Website categories</h3><button class="secondary" data-product-category="All">All · ${products.length}</button>${[...new Set(products.map(p=>p.category))].sort().map(c=>`<button class="secondary" data-product-category="${esc(c)}">${esc(c)} · ${products.filter(p=>p.category===c).length}</button>`).join('')}<p class="help">Website breadcrumbs and product types define these categories. Missing category evidence stays Uncategorized.</p></aside><div id="productLibraryList">${products.map(p=>{const cover=p.assets.find(a=>a.group==='product-images'&&a.preview)||p.assets.find(a=>a.preview),base='/creative-ai/api/brands/'+b.id+'/products/'+p.id;return `<button class="card product-profile-row" data-product="${p.id}" data-category="${esc(p.category)}">${cover?`<img src="${base}/${cover.id}/preview" alt="${esc(p.name)}">`:''}<div><span class="eyebrow">${esc(p.taxonomy.map(t=>t.name).join(' / ')||'Uncategorized')}</span><h3>${esc(p.name)}</h3><p>SKU: ${esc(p.sku||'See variants / not exposed')} · ${p.variants.length} variants</p><p>${p.assets.filter(a=>a.status==='stored').length} stored assets · ${p.assets.filter(a=>a.status==='linked').length} media links</p><small>Collected ${esc(new Date(p.collectedAt).toLocaleString())}</small></div></button>`;}).join('')||'<div class="card"><h3>No product profiles yet</h3><p>Add a SKU URL above, or use one in a new brief.</p></div>'}</div></div><div id="productProfile"></div>`;}
async function showProductProfile(b,id){const epoch=navigationEpoch,tabEpoch=brandTabEpoch,profileEpoch=++productProfileEpoch,p=await api('/creative-ai/api/brands/'+b.id+'/products/'+id);if(epoch!==navigationEpoch||tabEpoch!==brandTabEpoch||profileEpoch!==productProfileEpoch||activeBrand?.id!==b.id||brandTab!=='products')return;productLibrarySelection=p;history.replaceState(null,'','/creative-ai?brand='+encodeURIComponent(b.id)+'&tab=products&product='+encodeURIComponent(p.id));const base='/creative-ai/api/brands/'+b.id+'/products/'+p.id;$('#productProfile').innerHTML=`<section class="card"><span class="eyebrow">PRODUCT PROFILE · ${esc(p.brandName)}</span><h2>${esc(p.name)}</h2><p>${esc(p.taxonomy.map(t=>t.name).join(' / ')||'Uncategorized')} · ${esc(p.identityBasis)}</p><details><summary>Website product description</summary><p>${esc(p.description)}</p></details><p>SKU: ${esc(p.sku||'Not exposed at product level; see variants')} · Captured ${esc(new Date(p.collectedAt).toLocaleString())}</p><a href="${esc(p.pageUrl)}" target="_blank" rel="noopener">Official product page ↗</a><div class="bottom-actions"><button class="secondary" data-refresh-product="${p.id}">Refresh product assets</button><button class="primary" data-use-product="${p.id}" ${b.latestResearchId?'':'disabled'}>Use in a new brief →</button></div>${!b.latestResearchId?'<p class="help">Refresh brand research before starting a brief.</p>':''}<nav class="product-folder-nav" aria-label="Product asset folders">${['product-images','tiles','a-plus-content','videos','supporting-content'].map(g=>`<a href="#product-folder-${g}">${esc(productGroupLabel(g))} · ${p.assets.filter(a=>a.group===g).length}${(p.contentSections||[]).some(s=>s.group===g)?' media + '+p.contentSections.filter(s=>s.group===g).length+' text sections':''}</a>`).join('')}</nav><details><summary>Variants & options · ${p.variants.length}</summary>${p.variants.map(v=>`<p><b>${esc(v.name)}</b> · SKU ${esc(v.sku||'not exposed')} · ${v.available===null?'Availability unknown':v.available?'Available when collected':'Unavailable when collected'}</p>`).join('')||'<p>No variant metadata exposed.</p>'}<p>${esc(JSON.stringify(p.options))}</p></details><details><summary>Product information & source coverage</summary><p>${p.audit?'Identity audited during product research · '+esc(p.audit.identityStatus):'Archived website content; identity and feature audit will run when used in a brief.'}</p>${(p.audit?.facts||[]).map(f=>`<p><b>${esc(f.status)}</b> · ${esc(f.text)}</p>`).join('')}<p>${esc(p.limits.join(' '))}</p>${p.gaps.map(g=>`<p class="help">${esc(g)}</p>`).join('')}<p>${p.history.length} earlier snapshots retained.</p></details></section>${productCreativesHtml(p)}${['product-images','tiles','a-plus-content','videos','supporting-content'].map(group=>`<section class="card" id="product-folder-${group}"><h3>${esc(productGroupLabel(group))}</h3>${(p.contentSections||[]).filter(s=>s.group===group).map(s=>`<details><summary>${esc(s.heading)}</summary><p>${esc(s.text)}</p></details>`).join('')}<div class="product-assets-grid">${p.assets.filter(a=>a.group===group).map(a=>`<article class="product-asset">${a.preview?`<img loading="lazy" src="${base}/${a.id}/preview" alt="${esc(a.label)}">`:''}<b>${esc(a.label)}</b><p>${esc(a.status)}${a.bytes?' · '+(a.bytes/1024/1024).toFixed(2)+' MB':''}</p><p class="help">${esc(a.basis)} ${esc(a.note||'')}</p>${a.file?`<a href="${base}/${a.id}/original" download>Download original ↓</a>`:''} · <a href="${esc(a.url)}" target="_blank" rel="noopener">Website source ↗</a></article>`).join('')||'<p>No assets exposed in this group.</p>'}</div></section>`).join('')}`;const identityHtml=await skuIdentityHtml(b,p);if(epoch!==navigationEpoch||tabEpoch!==brandTabEpoch||profileEpoch!==productProfileEpoch||activeBrand?.id!==b.id||brandTab!=='products')return;$('#productProfile').insertAdjacentHTML('afterbegin',identityHtml);bindSkuIdentity(b,p);$('#productProfile').scrollIntoView({behavior:'smooth',block:'start'});}
function bindProductLibrary(b){const form=$('#productCaptureForm');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;$('#productCaptureProgress').textContent='Collecting product details and assets for '+b.name+'…';try{const p=await post('/creative-ai/api/brands/'+b.id+'/products',{brandName:b.name,url:form.elements.url.value});if(activeBrand?.id!==b.id||brandTab!=='products')return;await renderBrandTab('products');await showProductProfile(b,p.id);}catch(e){if(activeBrand?.id!==b.id||brandTab!=='products'||!form.isConnected)return;showError(form.querySelector('.form-error'),e);$('#productCaptureProgress').textContent='Collection did not complete. Saved profiles remain available.';}finally{button.disabled=false;}};$('#productLibraryList').onclick=e=>{const button=e.target.closest('[data-product]');if(button)showProductProfile(b,button.dataset.product).catch(e=>showError($('#brandWorkspaceError'),e));};$('#brandWorkspaceContent').querySelectorAll('[data-product-category]').forEach(button=>button.onclick=()=>{$('#productLibraryList').querySelectorAll('[data-product]').forEach(row=>row.hidden=button.dataset.productCategory!=='All'&&row.dataset.category!==button.dataset.productCategory);});$('#productProfile').onclick=async e=>{const refresh=e.target.closest('[data-refresh-product]'),use=e.target.closest('[data-use-product]');try{if(refresh){refresh.disabled=true;refresh.textContent='Refreshing assets…';const p=await post('/creative-ai/api/brands/'+b.id+'/products',{brandName:b.name,url:productLibrarySelection.pageUrl,refresh:true});if(activeBrand?.id!==b.id||brandTab!=='products')return;await renderBrandTab('products');await showProductProfile(b,p.id);}else if(use){const p=productLibrarySelection;if(!await startBrandBrief())return;$('#focusType').value='product';$('#focusType').dispatchEvent(new Event('change'));$('#productPageUrl').value=p.pageUrl;$('#productName').value=p.name.slice(0,160);$('#productIdentityId').value='';$('#productIdentitySelection').textContent=workspaceConfig.trustWebsiteProductImages?'Website photos are trusted. A single-variant SKU will use its archived product reference automatically.':'Select a verified identity from this product profile before generation.';saveDraft();}}catch(e){showError($('#brandWorkspaceError'),e);if(refresh)refresh.disabled=false;}};}

$('#productPageUrl').addEventListener('input',()=>{$('#productIdentityId').value='';$('#productIdentitySelection').textContent=workspaceConfig.trustWebsiteProductImages?'Official website product references are trusted; select an exact variant if the page offers multiple.':'Product URL changed. Choose its verified SKU identity in Product library.';saveDraft();});
async function skuIdentityHtml(b,p){const base='/creative-ai/api/brands/'+b.id+'/products/'+p.id,identities=await api(base+'/identities'),library=await api('/creative-ai/api/brands/'+b.id+'/assets');const photos=p.assets.filter(a=>a.group==='product-images'&&a.type==='image'&&a.status==='stored'),supplied=library.assets.filter(a=>a.status==='visual-reference'&&['png','jpg','jpeg','webp'].includes(a.format));return `<section class="card sku-identity"><span class="eyebrow">SKU REFERENCES</span><h2>Product references & dimensions</h2><p>Choose the exact variant and official reference. New creatives can change angle, lighting and framing while preserving product branding and documented technology. Colour, fabric and construction remain visual references for a recognisable SKU.</p>${workspaceConfig.trustWebsiteProductImages?`<p class="help">Official images from this exact product page are trusted under your current instruction. No manual image approval is needed. Dimensions are separate and remain unconfirmed unless supplied.</p><form id="websiteSkuForm"><div class="form-row"><label>Website variant<select name="variantId" required><option value="">Choose the exact variant…</option>${(p.variants.length?p.variants:[{id:'product',name:p.name}]).map(v=>`<option value="${esc(v.id)}" ${(p.variants.length<=1)?'selected':''}>${esc(v.name||p.name)} ${esc(v.sku||'')}</option>`).join('')}</select></label><label>Website product photograph<select name="assetId" required>${photos.map(a=>`<option value="${esc(a.id)}">${esc(a.label)} · ${a.id}</option>`).join('')}</select></label></div><div id="websiteSkuPreview"></div><p class="form-error error" hidden></p><button class="primary" ${photos.length?'':'disabled'}>Use website reference in brief →</button></form>`:''}${identities.map(i=>`<article class="sku-identity-row"><img loading="lazy" src="${base}/identities/${i.id}/reference" alt="Approved ${esc(i.variant.name)}"><div><span class="pill">${i.approval.basis.startsWith('Website reference trusted under')?'Trusted website reference':'Explicitly verified reference'}</span><h3>${esc(i.variant.name)}</h3><p>SKU ${esc(i.variant.sku)} · ${esc(i.variant.colour)} · ${esc(i.variant.size)}</p><p><b>Dimensions:</b> ${esc(skuDimensions(i.variant))}</p><p>Approved view: ${esc(i.reference.angle)} · ${i.reference.hasTransparency?'Transparent product layer':'Full photograph, including its original background'}</p><details><summary>Saved reference details</summary>${Object.entries(i.details).map(([k,v])=>`<p><b>${esc(k)}</b>: ${esc(v)}</p>`).join('')}<p class="help">${esc(i.approval.basis)} · ${esc(i.createdAt)}</p></details><button type="button" class="primary" data-use-identity="${i.id}">Use this SKU →</button></div></article>`).join('')||(workspaceConfig.trustWebsiteProductImages?'<p class="help">A source identity will be saved when you use a website reference. Single-variant SKU briefs can create it automatically.</p>':'<p class="help">No reference approved yet. Product-image generation is blocked until you verify a SKU identity.</p>')}<details><summary>${workspaceConfig.trustWebsiteProductImages?'Add dimensions or a custom reference':'Verify a SKU reference'}</summary><form id="skuIdentityForm"><label>Exact website variant<select name="variantId" required><option value="">Choose the variant…</option>${(p.variants.length?p.variants:[{id:'product',name:'Model as shown in the approved reference',sku:p.sku}]).map(v=>`<option value="${esc(v.id)}">${esc(v.name)} ${v.sku?'· '+esc(v.sku):''}</option>`).join('')}</select></label><div class="form-row"><label>SKU / explicit variant identifier<input name="sku" required maxlength="180"></label><label>Variant name<input name="variantName" required maxlength="240"></label></div><div class="form-row"><label>Colour / appearance<input name="colour" required maxlength="240" placeholder="Exact colour shown in the reference"></label><label>Size label<input name="size" required maxlength="240" placeholder="For example: Queen, King or three seater"></label></div><fieldset class="sku-dimensions"><legend>Product dimensions</legend><p class="help">Physical dimensions for this exact variant, separate from image pixels. Use the product specification; do not estimate from the photograph.</p><label>Dimensions available<select name="dimensionStatus"><option value="unknown">Not confirmed</option><option value="specified">Known from a product specification</option></select></label><div id="skuDimensionFields" hidden><div class="form-row"><label>Length / depth<input name="dimensionLength" type="number" min="0.000001" max="100000" step="any"></label><label>Width<input name="dimensionWidth" type="number" min="0.000001" max="100000" step="any"></label></div><div class="form-row"><label>Height / thickness (optional)<input name="dimensionHeight" type="number" min="0.000001" max="100000" step="any"></label><label>Unit<select name="dimensionUnit"><option value="cm">Centimetres</option><option value="mm">Millimetres</option><option value="in">Inches</option></select></label></div><label>Dimensions source / specification<input name="dimensionSource" maxlength="500" placeholder="Official variant specification, product page or supplied spec sheet"></label></div></fieldset><label>Configuration<input name="configuration" required maxlength="400" placeholder="For example: three seater, no ottoman, fixed legs"></label><label>Reference image<select name="reference" required><option value="">Choose the actual product reference…</option><optgroup label="Archived product photographs">${photos.map(a=>`<option value="product:${a.id}">${esc(a.label)} · ${a.id}</option>`).join('')}</optgroup><optgroup label="Supplied brand-library images">${supplied.map(a=>`<option value="brand:${a.id}">${esc(a.name)}</option>`).join('')}</optgroup></select></label><div id="skuReferencePreview"></div><p class="help">Images guide the complete generated creative; their original backgrounds and camera angles do not need to be retained. Upload extra photographs or renders through this brand’s Asset library.</p><div class="form-row"><label>Reference type<select name="referenceKind"><option value="photograph">Approved photograph</option><option value="render">Approved raster render</option></select></label><label>Approved camera view<input name="angle" required maxlength="180" placeholder="Front three-quarter; the exact supplied view"></label></div>${[['logoPlacement','Logo and label placement'],['construction','Shape, proportions, seams and panels'],['surface','Fabric, stitching, quilting and pattern'],['sections','Internal sections / cutaway evidence']].map(([key,label])=>`<label>${label}<textarea name="${key}" required maxlength="1200" placeholder="Describe only what this approved reference establishes; explicitly note anything not visible."></textarea></label>`).join('')}<label class="check-label"><input name="confirmed" type="checkbox" required> I inspected this reference and confirm it represents this exact SKU/variant and the physical details and stated dimensions above.</label><div class="form-error error" hidden></div><button class="primary">Save verified identity</button><p class="help">Each approval creates a separate immutable identity. Existing approvals and generated projects retain their original reference and hashes.</p></form></details></section>`;}
function bindSkuIdentity(b,p){bindWebsiteSku(b,p);const form=$('#skuIdentityForm'),base='/creative-ai/api/brands/'+b.id+'/products/'+p.id;form.elements.dimensionStatus.onchange=()=>{const known=form.elements.dimensionStatus.value==='specified';$('#skuDimensionFields').hidden=!known;for(const key of ['dimensionLength','dimensionWidth','dimensionSource'])form.elements[key].required=known;};form.elements.variantId.onchange=()=>{form.elements.dimensionStatus.value='unknown';for(const key of ['dimensionLength','dimensionWidth','dimensionHeight','dimensionSource'])form.elements[key].value='';form.elements.dimensionStatus.onchange();const v=p.variants.find(v=>v.id===form.elements.variantId.value);form.elements.sku.value=v?.sku||(v?'variant-'+v.id:p.sku||'');form.elements.variantName.value=v?.name||p.name;};form.elements.reference.onchange=()=>{const v=form.elements.reference.value;$('#skuReferencePreview').innerHTML=v.startsWith('product:')?`<img src="${base}/${encodeURIComponent(v.slice(8))}/preview" alt="Selected product reference">`:v.startsWith('brand:')?`<img src="/creative-ai/api/brands/${b.id}/assets/${encodeURIComponent(v.slice(6))}/preview" alt="Selected supplied reference">`:'';};form.onsubmit=async e=>{e.preventDefault();const epoch=navigationEpoch,button=form.querySelector('button'),values=Object.fromEntries(new FormData(form));button.disabled=true;form.querySelector('.form-error').hidden=true;try{const details=Object.fromEntries(['logoPlacement','construction','surface','sections'].map(k=>[k,values[k]]));await post(base+'/identities',{...values,brandName:b.name,confirmed:form.elements.confirmed.checked,details,dimensions:values.dimensionStatus==='specified'?{status:'specified',length:Number(values.dimensionLength),width:Number(values.dimensionWidth),height:values.dimensionHeight?Number(values.dimensionHeight):null,unit:values.dimensionUnit,source:values.dimensionSource}:{status:'unknown'}});if(epoch!==navigationEpoch||activeBrand?.id!==b.id||brandTab!=='products')return;await showProductProfile(b,p.id);}catch(e){if(epoch===navigationEpoch&&form.isConnected)showError(form.querySelector('.form-error'),e);}finally{button.disabled=false;}};$('#productProfile').querySelectorAll('[data-use-identity]').forEach(button=>button.onclick=async()=>{const epoch=navigationEpoch;button.disabled=true;try{const identity=await api(base+'/identities/'+button.dataset.useIdentity);if(epoch!==navigationEpoch||activeBrand?.id!==b.id)return;if(!await startBrandBrief())return;$('#focusType').value='product';productFocusFields();$('#productPageUrl').value=p.pageUrl;$('#productName').value=p.name.slice(0,160);$('#productIdentityId').value=identity.id;$('#productIdentitySelection').textContent='SKU reference '+identity.variant.sku+' · '+identity.variant.name+' · '+skuDimensions(identity.variant)+' · '+identity.reference.angle;saveDraft();}catch(e){showError($('#brandWorkspaceError'),e);}finally{button.disabled=false;}});}

async function loadRequestedIdentities(j){const epoch=navigationEpoch,brand=brandList.find(b=>b.id===j.brandId);if(!brand)return;const products=await api('/creative-ai/api/brands/'+brand.id+'/products'),groups=await Promise.all(products.map(async p=>({p,identities:await api('/creative-ai/api/brands/'+brand.id+'/products/'+p.id+'/identities')})));if(epoch!==navigationEpoch||currentJob?.id!==j.id||j.status!=='needs-input')return;const select=$('#requestedProductIdentity');select.innerHTML='<option value="">Choose an approved product identity</option>'+groups.flatMap(({p,identities})=>identities.map(i=>'<option value="'+esc(i.id)+'" data-url="'+esc(p.pageUrl)+'">'+esc(i.variant.sku+' · '+i.variant.name+' · '+i.variant.size+' · '+skuDimensions(i.variant)+' · '+i.reference.angle)+'</option>')).join('');select.onchange=()=>{$('#requestedProductPage').value=select.selectedOptions[0]?.dataset.url||'';};$('#requestedProductPage').oninput=()=>{if(select.selectedOptions[0]?.dataset.url!==$('#requestedProductPage').value.trim())select.value='';};$('#requestedIdentityHelp').textContent=groups.some(g=>g.identities.length)?'Select the exact SKU and approved view. Its official URL is filled below.':'No approved identities yet. Open Products to approve the exact SKU reference, then return to this saved project.';$('#manageRequestedIdentity').onclick=async()=>{brandTab='products';await openBrand(brand.id);};}

function protectedProductReasoning(unit){if(unit?.productReferencePolicy){const r=unit.productReferencePolicy,checks=unit.productObservations||[];return reasonCard('SKU fidelity review','<p><b>'+esc(r.sku)+'</b> · '+esc(r.productName)+'</p><p>Angle, lighting, framing and scene may change. Product branding and documented technology must be preserved. Other details are compared for recognisability, without a pixel-match requirement.</p>'+(checks.length?'':'<p>SKU visual checks are unavailable or have not completed.</p>')+checks.map(c=>'<p><b>'+esc(c.criterion)+': '+esc(c.status)+'</b> · '+esc(c.evidence.observation)+'</p>'+(c.status==='fail'?'<p>Correction: '+esc(c.correction)+'</p>':'')).join('')+'<p class="help">Source hashes establish reference provenance. Visual model review is not a guarantee of zero hallucinations.</p>');}const p=unit?.productProtection,proof=unit?.productPixelProof;if(!p)return '';return reasonCard('Protected product identity','<p><b>'+esc(p.variant.sku)+'</b> · '+esc(p.variant.name)+' · '+esc(p.reference.angle)+'</p><p><b>Dimensions:</b> '+esc(skuDimensions(p.variant))+'</p>'+(p.variant.dimensions?.status==='specified'?'<p class="help">Specification source: '+esc(p.variant.dimensions.source)+'</p>':'')+'<p>'+esc(p.approval.basis)+'</p><p>The supplied product reference is protected for this SKU. The renderer places its pixels after generating the surrounding scene; product details are not redrawn.</p><p><b>Export pixel check:</b> '+esc(proof?.protectedPixelVerification||'Proof unavailable')+'</p><p class="help">Only uniform reduction and translation are allowed. Transparent edges are blended. This check preserves the approved product layer; the complete scene still needs its artwork review.</p><details><summary>Approved physical details & reference</summary>'+Object.entries(p.details).map(([key,value])=>'<p><b>'+esc(key)+'</b>: '+esc(value)+'</p>').join('')+'<p class="help">Reference hash: '+esc(p.reference.rasterHash)+'</p></details>');}

function skuDimensions(v){const d=v?.dimensions;if(!d||d.status!=='specified')return 'Dimensions not confirmed';return 'L/D '+d.length+' × W '+d.width+(d.height!==null?' × H '+d.height:'')+' '+(d.unit==='in'?'inches':d.unit)+(d.height===null?' · height not confirmed':'');}

function bindWebsiteSku(b,p){const form=$('#websiteSkuForm');if(!form)return;const base='/creative-ai/api/brands/'+b.id+'/products/'+p.id;const preview=()=>{$('#websiteSkuPreview').innerHTML=form.elements.assetId.value?'<img style="max-width:100%;max-height:220px;object-fit:contain" src="'+base+'/'+encodeURIComponent(form.elements.assetId.value)+'/preview" alt="Trusted website product photograph">':'';};form.elements.assetId.onchange=preview;preview();form.onsubmit=async event=>{event.preventDefault();const epoch=navigationEpoch,button=form.querySelector('button');button.disabled=true;form.querySelector('.form-error').hidden=true;try{const i=await post(base+'/identities',{action:'trust-website',brandName:b.name,variantId:form.elements.variantId.value,assetId:form.elements.assetId.value});if(epoch!==navigationEpoch||activeBrand?.id!==b.id)return;if(!await startBrandBrief())return;$('#focusType').value='product';productFocusFields();$('#productPageUrl').value=p.pageUrl;$('#productName').value=p.name.slice(0,160);$('#productIdentityId').value=i.id;$('#productIdentitySelection').textContent='Trusted website SKU '+i.variant.sku+' · '+skuDimensions(i.variant);saveDraft();}catch(error){if(epoch===navigationEpoch&&form.isConnected)showError(form.querySelector('.form-error'),error);}finally{button.disabled=false;}};}

let productionTarget=null;
function openProductionEvidence(key){const [route,formatId]=key.split('|'),proof=currentJob?.printProofs?.find(p=>p.route===route&&p.formatId===formatId);if(!proof?.physicalProof)return;productionTarget={route,formatId,proof,jobId:currentJob.id,brandId:currentJob.brandId};const input=(name,label,type='text',value='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0.001" step="any"':'maxlength="800"'}></label>`,finding=(name,label)=>`<label>${label}<select name="${name}" required><option value="">Select observed result</option><option value="pass">Pass from actual check</option><option value="fail">Fail from actual check</option></select></label>`;$('#productionEvidenceFields').innerHTML=`<p><b>${esc(proof.name)}</b> · ${esc(route)}</p><p class="help">Proof ${esc(proof.pdfHash.slice(0,16))} · ${esc(proof.preflight.approvalBasis)}</p>${proof.preflight.checks.map(c=>`<p class="help"><b>${esc(c.status)} · ${esc(c.id)}</b>: ${esc(c.detail)}</p>`).join('')}${input('operatorName','Printer / outdoor operator')}${input('specReference','Exact operator template / specification reference')}${input('stock','Stock / substrate and GSM where applicable')}${input('finishing','Finishing, folds, die cuts, seams, eyelets or mounting')}${input('requiredPpi','Finished-size PPI required by this operator','number',proof.pages[0]?.requiredPpi||300)}<label>Operator file requirement<select name="fileAcceptance" required><option value="unknown">Unconfirmed</option><option value="rgb-raster-pdf">Operator explicitly accepts this RGB raster PDF</option><option value="cmyk-pdfx-vector">Requires CMYK, PDF/X or vector production file</option></select></label><label><input type="checkbox" name="largePageUserUnitAccepted">Operator confirmed large-page PDF/RIP support (if applicable)</label><label><input type="checkbox" name="printedAtActualSize">Actually printed at 100% / Actual Size</label>${input('measuredRulerMm','Measured length of the 50 mm calibration line','number')}<label><input type="checkbox" name="completePhysicalProof">Checked the complete artwork at physical / installed size, including areas outside sample crops</label>${input('distanceM','Actual reading distance, metres','number')}${input('dwellSeconds','Available reading time, seconds','number')}${finding('readability','Essential message and qualifiers at that distance')}${finding('templateMatch','Vendor template, trim, fold and hardware clearance')}${finding('stockColourFinishing','Actual stock, colour, finishing and mounting sample')}${input('checkedBy','Person who performed / witnessed these checks')}${input('evidenceReference','Operator approval or observed proof record reference')}`;$('#productionEvidenceStatus').textContent='';$('#productionDialog').showModal();}
$('#productionClose').onclick=()=>$('#productionDialog').close();
$('#productionEvidenceForm').onsubmit=async e=>{e.preventDefault();const target=productionTarget,job=currentJob;if(!target||!job||job.id!==target.jobId||job.brandId!==target.brandId)return;const form=e.currentTarget,data=Object.fromEntries(new FormData(form)),contract={...data};for(const k of ['requiredPpi','measuredRulerMm','distanceM','dwellSeconds'])contract[k]=Number(data[k]);for(const k of ['largePageUserUnitAccepted','printedAtActualSize','completePhysicalProof'])contract[k]=form.elements[k].checked;const button=form.querySelector('[type="submit"]');button.disabled=true;try{const brand=brandList.find(b=>b.id===job.brandId);if(!brand)throw Error('Saved project brand is unavailable.');const report=await post('/creative-ai/api/jobs/'+job.id+'/production-evidence',{brandName:brand.name,route:target.route,formatId:target.formatId,masterPdfHash:target.proof.pdfHash,proofHash:target.proof.physicalProof.proofHash,contract});if(productionTarget!==target||currentJob?.id!==target.jobId)return;currentJob.productionChecks??=[];currentJob.productionChecks.push(report);$('#productionEvidenceStatus').innerHTML=`<b>${esc(report.status.replaceAll('-',' '))}</b><p>${esc(report.releaseNote)}</p><a href="${esc(report.reportUrl)}" download>Download recorded check report ↓</a>`;render(currentJob);}catch(err){if(productionTarget===target)$('#productionEvidenceStatus').textContent=err.message;}finally{button.disabled=false;}};
